import { createContext } from "react";
import React from "react";

/*
Creates context for the toggles on the stat buttons
*/

interface Toggle {
    isToggled : boolean;
    setToggled : (toggle : boolean) => void;
};

interface ToggleMap {
    toggleMap : Record<string, Toggle>;
    updateMap : (record : Record<string, Toggle>) => void
}

function changeToggle(toggle : boolean){
    toggle = !toggle;
}

export const Toggles = React.createContext<ToggleMap>({toggleMap: {}, updateMap: () => {}});

